<script setup>
import {computed,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {api,currentUser} from '../api'
import RemoteSelect from './RemoteSelect.vue'
import BusinessFilters from './BusinessFilters.vue'
import {translate,choices,field,creation,reason,note,student,bed,state} from '../business-modules'
import {moduleForRole} from '../permissions'
const props=defineProps({kind:String})
const role=computed(()=>currentUser.value?.role),config=computed(()=>moduleForRole(props.kind,role.value)),staff=computed(()=>['admin','manager'].includes(role.value))
const rows=ref([]),error=ref(''),notice=ref(''),busy=ref(false),search=ref(''),page=ref(1)
const dialog=ref(null),form=reactive({}),photo=ref(null),detail=ref(null),file=ref(null),preview=ref(null),previewKind=ref('')
const selectedStudents=ref([]),selectedBuildings=ref([]),settings=reactive({checkoutRequiresSettledBills:true,checkoutRequiresReturnedAssets:true,allResidentsCanReport:true})
const create=computed(()=>config.value?creation(props.kind,role.value):null)
const total=ref(0),visible=rows
const optionEpoch=ref(0),filters=reactive({state:'',building:'',from:'',to:''})
let requestVersion=0,searchTimer
const base=path=>path.startsWith('!')?'/'+path.slice(1):'/business'+path
const money=value=>(Number(value||0)/100).toFixed(2)+' 元'
function format(key,value){if(props.kind==='repairs'&&key==='assignee'&&!value)return '等待派单';if(value==null||value==='')return '—';if(key.endsWith('_cents'))return money(value);if(['enabled','is_read','force_password_change'].includes(key))return Number(value)?'是':'否';if(Array.isArray(value))return value.join('、')||'—';if(key==='role')return translate(String(value).toUpperCase());if(key.endsWith('_at')||key==='reservation_until')return String(value).replace('T',' ').slice(0,19);return translate(value)}
async function load(){const version=++requestVersion;busy.value=true;error.value='';try{
  if(!config.value){rows.value=[];total.value=0;return}
  if(props.kind==='batch'){rows.value=[]}
  else if(props.kind==='settings'){const data=await api('/business/settings');Object.assign(settings,{checkoutRequiresSettledBills:data.checkout_requires_settled_bills,checkoutRequiresReturnedAssets:data.checkout_requires_returned_assets,allResidentsCanReport:data.all_residents_can_report})}
  else {const resource=props.kind==='archives'?'students':props.kind;const params=new URLSearchParams({page:page.value,size:20,search:search.value,...filters});const data=await api(`/business/lists/${resource}?${params}`);if(version!==requestVersion)return;rows.value=data.items;total.value=data.total;const last=Math.max(1,Math.ceil(data.total/20));if(page.value>last){page.value=last;return load()}}
}catch(e){if(version===requestVersion)error.value=e.message}finally{if(version===requestVersion)busy.value=false}}
function refresh(){optionEpoch.value++;return load()}
function searchChanged(){clearTimeout(searchTimer);requestVersion++;busy.value=true;searchTimer=setTimeout(()=>{page.value=1;load()},300)}
async function turnPage(delta){clearTimeout(searchTimer);page.value+=delta;await load()}
function values(f){return f.options||[]}
async function open(spec){busy.value=true;error.value='';try{Object.keys(form).forEach(k=>delete form[k]);for(const f of spec.fields||[]){form[f.key]=spec.defaults?.[f.key]??(f.multiple?[]:f.type==='checkbox'?true:f.required&&f.type==='select'&&values(f).length?values(f)[0].value:f.type==='number'?(f.min??0):'')};photo.value=null;dialog.value=spec}catch(e){error.value=e.message}finally{busy.value=false}}
function bodyFor(spec){const body={};for(const f of spec.fields||[]){if(spec.omit?.includes(f.key))continue;let value=form[f.key];if(f.multiple){value=value.map(v=>f.number?Number(v):v)}else if(f.number)value=value===''||value==null?null:Number(value);else if(f.type==='number'&&f.key!=='amount')value=Number(value);body[f.key]=value}return body}
async function submit(){busy.value=true;error.value='';const spec=dialog.value;try{const target=typeof spec.path==='function'?spec.path(form):spec.path;let result;
  if(spec.multipart){const data=new FormData();Object.entries(bodyFor(spec)).forEach(([k,v])=>data.append(k,v));if(photo.value)data.append('image',photo.value);result=await api(base(target),{method:spec.method||'POST',body:data})}
  else result=await api(base(target),{method:spec.method||'POST',body:spec.fields?.length?bodyFor(spec):undefined});
  if(spec.photo&&!spec.multipart&&photo.value){const data=new FormData();data.append('image',photo.value);await api(`/business/inspections/${spec.imageId||result.id}/image${spec.rectify?'?rectification=true':''}`,{method:'POST',body:data})}
  dialog.value=null;notice.value=result?.message||spec.successMessage||'操作已完成';await refresh();
}catch(e){error.value=e.message}finally{busy.value=false}}
const decisionFields=(includeBed=false)=>[field('approve','是否批准','checkbox'),...(includeBed?[bed()]:[]),note()]
function actions(row){if(!config.value)return [];const list=[];const add=(label,spec)=>list.push({label,run:()=>open({...spec,title:spec.title||label})});
 if(props.kind==='archives'&&role.value==='admin'&&!Number(row.has_account)&&row.lifecycle==='ENROLLED')add('开通学生账号',{path:`/students/${row.id}/account`,fields:[field('newPassword','初始密码','password',{required:true,minlength:8,max:72}),reason()],help:'仅为已有在校学生补建登录账号，首次登录须修改密码。'});
 switch(props.kind){
 case 'beds':if(staff.value){if(row.state!=='OCCUPIED'){add('床位状态 / 预留',{path:`/beds/${row.id}/state`,method:'PATCH',fields:[state('AVAILABLE','RESERVED','DISABLED'),{...student(),required:false},field('until','预留到期时间','datetime-local'),reason()],defaults:{state:row.state}});if(row.state==='AVAILABLE'&&row.room_state==='ACTIVE')add('安排入住',{path:'/housing/move',fields:[student(),bed(),reason()],defaults:{bedId:row.id}})}}break;
 case 'rooms':if(staff.value)add('调整状态',{path:`/rooms/${row.id}/state`,method:'PATCH',fields:[state('ACTIVE','MAINTENANCE','CLOSED'),reason()],defaults:{state:row.room_state}});break;
 case 'applications':if(['admin','manager','counselor'].includes(role.value)&&row.state==='PENDING')add('审批',{path:`/housing/applications/${row.id}/review`,fields:decisionFields(row.kind!=='CHECKOUT'),defaults:{bedId:row.target_bed_id??''}});
   if(staff.value&&row.state==='APPROVED')add('办理完成',{path:`/housing/applications/${row.id}/complete`,fields:[],help:'办理时再次检查床位、账单及物品交接，成功后更新实际入住记录。'});
   if(['PENDING','APPROVED'].includes(row.state)&&role.value!=='worker')add('撤销申请',{path:`/housing/applications/${row.id}/cancel`,fields:[]});break;
 case 'archives':if(role.value==='admin')add('维护学籍 / 归档',{path:`/students/${row.id}/profile`,method:'PATCH',fields:[field('lifecycle','学籍状态','select',{required:true,options:choices('ENROLLED','GRADUATED','SUSPENDED','WITHDRAWN')}),field('college','学院','text',{max:100}),field('major','专业','text',{max:100}),field('counselor','辅导员账号','text',{max:50}),reason()],defaults:{lifecycle:row.lifecycle,college:row.college||'',major:row.major||'',counselor:row.counselor||''},help:'毕业、休学或退学前需办理退宿并处理费用与物品交接，历史档案持续保留。'});break;
 case 'accounts':if(row.role!=='admin'){add('启用 / 楼栋范围',{path:`/accounts/${encodeURIComponent(row.username)}/state`,method:'PATCH',fields:[field('enabled','账号启用','checkbox'),field('buildingIds','负责楼栋（仅宿管）','select',{source:'buildings',multiple:true,number:true}),reason()],defaults:{enabled:!!row.enabled,buildingIds:row.buildingIds||[]}});add('重置密码',{path:`/accounts/${encodeURIComponent(row.username)}/reset-password`,fields:[field('newPassword','新初始密码','password',{required:true,minlength:8,max:72}),reason()],help:'将使该账号其他登录会话失效，并要求下次登录修改初始密码。'})}break;
 case 'announcements':if(!row.is_read)add('标为已读',{path:`/announcements/${row.id}/read`,fields:[]});break;
 case 'notifications':if(!row.is_read)add('标为已读',{path:`/notifications/${row.id}/read`,fields:[]});break;
 case 'stays':if(['admin','manager','counselor'].includes(role.value)&&row.state==='PENDING')add('审核',{path:`/stays/${row.id}/review`,fields:decisionFields()});if(row.state==='APPROVED')add('登记返校',{path:`/stays/${row.id}/return`,fields:[]});break;
 case 'visitors':if(staff.value&&!row.left_at)add('登记离开',{path:`/visitors/${row.id}/leave`,fields:[]});break;
 case 'inspections':if(row.image_path)list.push({label:'检查图片',href:`/api/business/inspections/${row.id}/image`});if(row.rectify_image_path)list.push({label:'整改图片',href:`/api/business/inspections/${row.id}/image?rectification=true`});
   if(row.state==='OPEN')add('提交整改',{path:`/inspections/${row.id}/rectify`,fields:[note()],photo:true,rectify:true,imageId:row.id});if(staff.value&&row.state==='SUBMITTED')add('复查',{path:`/inspections/${row.id}/review`,fields:[field('approve','整改通过','checkbox'),note()]});break;
 case 'bills':list.push({label:'缴费 / 退款流水',run:()=>show(`/bills/${row.id}/payments`,'账单流水',[['kind','类型'],['amount_cents','金额'],['method','方式'],['reference_no','凭据编号'],['reason','说明'],['actor','登记人'],['created_at','时间']])});
   if(role.value==='admin'&&row.state==='ACTIVE'){add('登记缴费 / 退款',{path:`/bills/${row.id}/payments`,fields:[field('kind','登记类型','select',{required:true,options:choices('PAYMENT','REFUND')}),field('amount','金额（元）','number',{required:true,min:.01,step:.01}),field('method','收退款方式','select',{required:true,options:choices('BANK','CASH','WECHAT','ALIPAY','OTHER')}),field('referenceNo','唯一凭据 / 流水编号','text',{required:true,max:100}),reason()],help:'仅登记已核实的收退款流水，不会发起第三方支付。'});if(Number(row.net_paid_cents)===0)add('作废账单',{path:`/bills/${row.id}/void`,fields:[note()]})}break;
 case 'assets':if(staff.value){if(row.state==='AVAILABLE')add('登记领用',{path:`/assets/${row.id}/issue`,fields:[student(),note()]});if(row.state!=='ISSUED'&&row.state!=='RETIRED')add('调整资产状态',{path:`/assets/${row.id}/state`,method:'PATCH',fields:[state('AVAILABLE','REPAIR','LOST','RETIRED'),reason()],defaults:{state:row.state}})}break;
 case 'handovers':if(staff.value&&!row.returned_at)add('归还 / 损坏 / 丢失',{path:`/handovers/${row.id}/return`,fields:[field('condition','交接情况','select',{required:true,options:choices('GOOD','DAMAGED','LOST')}),note()]});break;
 case 'repairs':list.push({label:'处理记录',run:()=>show(`/repairs/${row.id}/events`,'工单处理记录',[['actor','处理人'],['action','操作'],['note','说明'],['created_at','时间']])});if(row.image_path)list.push({label:'故障图片',href:`/api/repairs/${row.id}/image`});
   if(staff.value&&!['已完成','待验收'].includes(row.status))add(row.assignee?'改派维修人员':'派单给维修人员',{successMessage:'派单成功，维修人员刷新“我的维修工单”即可查看，报修人也会收到通知。',path:`/repairs/${row.id}/dispatch`,fields:[field('assignee','维修人员','select',{required:true,source:'workers'}),field('priority','优先级（默认自动，可人工调整）','select',{required:true,options:choices('AUTO','NORMAL','URGENT')}),note()],defaults:{assignee:row.assignee||'',priority:row.priority_source==='MANUAL'?row.priority:'AUTO'}});
   if((staff.value||role.value==='worker')&&row.assignee&&row.status==='待处理')add('开始处理',{path:`/repairs/${row.id}/start`,fields:[note()]});
   if((staff.value||role.value==='worker')&&row.assignee&&row.status==='处理中')add('提交验收',{path:`/repairs/${row.id}/finish`,fields:[note()]});
   if(role.value==='student'&&row.status==='待验收')add('验收 / 退回重修',{path:`/repairs/${row.id}/review`,fields:[field('approve','验收通过','checkbox'),field('rating','评价（1–5）','number',{min:1,max:5}),note()]});break;
 }
 return list;
}
async function show(path,title,columns){try{detail.value={title,columns,rows:await api(base(path))}}catch(e){error.value=e.message}}
async function importPreview(){if(!file.value?.files[0]){error.value='请先选择模板文件';return}busy.value=true;error.value='';try{const data=new FormData();data.append('file',file.value.files[0]);preview.value=await api('/business/imports/preview',{method:'POST',body:data});previewKind.value='imports'}catch(e){error.value=e.message}finally{busy.value=false}}
async function template(){try{const blob=await api('/business/imports/template',{download:true});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='学生导入模板.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=e.message}}
async function allocate(){busy.value=true;error.value='';try{preview.value=await api('/business/allocations/preview',{method:'POST',body:{studentIds:selectedStudents.value.map(Number),buildingIds:selectedBuildings.value.map(Number)}});previewKind.value='allocations'}catch(e){error.value=e.message}finally{busy.value=false}}
async function confirmPreview(){busy.value=true;error.value='';try{await api(`/business/${previewKind.value}/${preview.value.previewId}/confirm`,{method:'POST'});preview.value=null;selectedStudents.value=[];selectedBuildings.value=[];notice.value='整批已执行成功';await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
async function saveSettings(){busy.value=true;error.value='';try{await api('/business/settings',{method:'PUT',body:settings});notice.value='业务规则已保存'}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
watch(currentUser,()=>{optionEpoch.value++})
onBeforeUnmount(()=>{clearTimeout(searchTimer);requestVersion++})
</script>
<template>
 <div v-if="!config" class="alert" role="alert">无权查看此页面。</div>
 <template v-else>
 <div class="page-heading"><div><span class="eyebrow">CAMPUS SERVICES</span><h1>{{config.title}}</h1><p class="muted">{{config.description || (kind==='repairs'?'派单、维修、验收与处理记录':kind==='bills'?'费用分摊、线下收退款登记与欠费查询':'按你的角色和负责范围展示业务记录')}}</p></div><div class="actions"><button :disabled="busy" @click="refresh">刷新</button><button v-if="create" class="primary" :disabled="busy" @click="open(create)">＋ {{create.title}}</button></div></div>
 <div v-if="error" class="alert sticky" role="alert">{{error}}<button @click="error=''">关闭</button></div><div v-if="notice" class="notice">{{notice}}</div>
 <template v-if="kind==='batch'"><section class="card padded"><h2>学生名单导入</h2><p class="muted">下载模板后填写资料，每批最多 500 人。新增账号需填写包含字母与数字的初始密码；预览不会返回密码，首次登录须改密。</p><div class="actions"><button @click="template">下载 XLSX 模板</button><input ref="file" type="file" accept=".xlsx" aria-label="学生名单文件"><button class="primary" :disabled="busy" @click="importPreview">校验并预览导入</button></div></section><section class="card padded"><h2>新生床位分配</h2><p class="muted">按性别和可用床位安排，优先将同年级同班学生安排在一起。请选择学生及目标楼栋，预览后再执行。</p><form class="form-grid" @submit.prevent="allocate"><label>选择未入住学生<RemoteSelect :key="'students-'+optionEpoch" v-model="selectedStudents" source="students" label="选择未入住学生" multiple required number unhoused /></label><label>选择目标楼栋<RemoteSelect :key="'buildings-'+optionEpoch" v-model="selectedBuildings" source="buildings" label="选择目标楼栋" multiple required number /></label><div class="form-footer"><button class="primary" :disabled="busy">生成分配预览</button></div></form></section>
 <section v-if="preview" class="card padded"><div class="modal-heading"><h2>{{previewKind==='imports'?'名单导入预览':'床位分配预览'}} · {{preview.items.length}} 人</h2><button @click="preview=null">取消预览</button></div><p class="muted">预览 15 分钟内有效，确认时重新校验数据；任何一条冲突都会撤销整批操作。</p><div class="table-scroll"><table><thead><tr><th>学号</th><th>姓名</th><th v-if="previewKind==='imports'">班级</th><th v-else>分配结果</th></tr></thead><tbody><tr v-for="(r,i) in preview.items" :key="i"><td>{{r.studentId&&previewKind==='imports'?r.studentId:r.studentNumber}}</td><td>{{r.name}}</td><td>{{previewKind==='imports'?r.className:`${r.room} · ${r.bedNumber} 号床`}}</td></tr></tbody></table></div><div class="form-footer"><button class="primary" :disabled="busy" @click="confirmPreview">确认执行本批次</button></div></section></template>
 <section v-else-if="kind==='settings'" class="card padded"><h2>业务规则</h2><form @submit.prevent="saveSettings"><label class="checkbox-line"><input v-model="settings.checkoutRequiresSettledBills" type="checkbox">退宿 / 跨宿舍调动前须结清费用</label><label class="checkbox-line"><input v-model="settings.checkoutRequiresReturnedAssets" type="checkbox">退宿 / 跨宿舍调动前须完成物品交接</label><label class="checkbox-line"><input v-model="settings.allResidentsCanReport" type="checkbox">允许所有已入住学生报修（关闭后仅宿舍长可报修）</label><div class="form-footer"><button class="primary" :disabled="busy">保存规则</button></div></form></section>
 <section v-else class="card"><div v-if="kind==='repairs'" class="padded"><p class="muted">优先级按故障描述自动判断，仅供分流；派单时可人工调整并填写说明。未完成工单按紧急程度优先、同级按提交时间排序。流程：提交报修 → 管理员 / 宿管派单 → 维修人员处理 → 提交验收 → 报修人 / 宿舍长确认。</p><button v-if="staff" :disabled="busy" @click="filters.state='WAITING_ASSIGNMENT';search='';filters.building='';filters.from='';filters.to='';page=1;load()">查看待派单工单</button><p v-if="role==='worker'" class="muted">未派给你的工单不会出现在这里；如报修已提交但列表为空，请联系管理员或宿管派单。</p></div><div class="table-toolbar"><span>共 {{total}} 条记录</span><input v-model="search" placeholder="搜索当前业务记录" aria-label="搜索业务记录" @input="searchChanged"></div><BusinessFilters :kind="kind" :filters="filters" @change="Object.assign(filters,$event);searchChanged()" /><div class="table-scroll"><table><thead><tr><th v-for="[key,label] in config.columns" :key="key">{{label}}</th><th>操作</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id??row.room_id"><td v-for="[key] in config.columns" :key="key" :class="{description:['content','detail','reason','detail_json','description','review_note','completion_note'].includes(key)}"><span v-if="['state','room_state','lifecycle','status'].includes(key)" class="badge">{{format(key,row[key])}}</span><template v-else>{{format(key,row[key])}}</template></td><td><div class="row-actions business-row-actions"><template v-for="action in actions(row)" :key="action.label"><a v-if="action.href" :href="action.href" target="_blank" rel="noopener">{{action.label}}</a><button v-else class="text-button" :disabled="busy" @click="action.run">{{action.label}}</button></template></div></td></tr><tr v-if="!visible.length"><td :colspan="config.columns.length+1" class="empty">{{busy?'正在加载…':'暂无业务记录'}}</td></tr></tbody></table></div><div class="pagination"><span>每页 20 条</span><div class="actions"><button :disabled="busy||page<=1" @click="turnPage(-1)">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/20))}}</span><button :disabled="busy||page*20>=total" @click="turnPage(1)">下一页</button></div></div></section>
 <div v-if="dialog" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" :aria-label="dialog.title"><div class="modal-heading"><h2>{{dialog.title}}</h2><button :disabled="busy" @click="dialog=null">关闭</button></div><p v-if="dialog.help" class="muted">{{dialog.help}}</p><form class="form-grid" @submit.prevent="submit"><label v-for="f in dialog.fields" :key="f.key" :class="{ 'span-all':f.type==='textarea', 'checkbox-line':f.type==='checkbox'}">{{f.label}}<RemoteSelect v-if="f.source" v-model="form[f.key]" :source="f.source" :label="f.label" :required="f.required" :multiple="f.multiple" :number="f.number" /><select v-else-if="f.type==='select'" v-model="form[f.key]" :aria-label="f.label" :required="f.required" :multiple="f.multiple" :size="f.multiple?5:undefined"><option v-if="!f.multiple" value="">请选择{{f.required?'':'（可不填）'}}</option><option v-for="o in values(f)" :key="o.value" :value="o.value">{{o.label}}</option></select><textarea v-else-if="f.type==='textarea'" v-model="form[f.key]" :aria-label="f.label" :required="f.required" :maxlength="f.max" rows="3"></textarea><input v-else-if="f.type==='checkbox'" v-model="form[f.key]" :aria-label="f.label" type="checkbox"><input v-else v-model="form[f.key]" :aria-label="f.label" :type="f.type" :required="f.required" :maxlength="f.type==='number'?undefined:f.max" :minlength="f.minlength" :min="f.min" :max="f.type==='number'?f.max:undefined" :step="f.step" :autocomplete="f.type==='password'?'new-password':undefined"></label><label v-if="dialog.photo" class="span-all">图片（可选，PNG/JPEG，不超过 5MB）<input type="file" accept="image/png,image/jpeg" @change="photo=$event.target.files[0]"></label><div class="form-footer"><button type="button" :disabled="busy" @click="dialog=null">取消</button><button class="primary" :disabled="busy">{{busy?'正在提交…':'确认提交'}}</button></div></form></section></div>
 <div v-if="detail" class="modal-backdrop"><section class="modal wide" role="dialog" aria-modal="true" :aria-label="detail.title"><div class="modal-heading"><h2>{{detail.title}}</h2><button @click="detail=null">关闭</button></div><div class="table-scroll"><table><thead><tr><th v-for="[key,label] in detail.columns" :key="key">{{label}}</th></tr></thead><tbody><tr v-for="(row,i) in detail.rows" :key="i"><td v-for="[key] in detail.columns" :key="key">{{format(key,row[key])}}</td></tr><tr v-if="!detail.rows.length"><td :colspan="detail.columns.length" class="empty">暂无记录</td></tr></tbody></table></div></section></div>
 </template>
</template>
